function renderScroll(){scrollFrame=0;const max=root.scrollHeight-innerHeight,ratio=max>0?Math.min(1,Math.max(0,scrollY/max)):0;
 // Batch geometry reads before style writes.
 const tops=cards.map(card=>card.getBoundingClientRect().top),sectionTops=sections.map(section=>section.getBoundingClientRect().top),canStack=motionEnabled()&&desktopStack.matches;
 $('.scroll-progress').style.transform='scaleX('+ratio+')';

 surfaces.forEach((surface,i)=>{const next=tops[i+1];const progress=canStack&&next!==undefined?Math.min(1,Math.max(0,(innerHeight-next)/(innerHeight-120))):0;surface.style.setProperty('--stack-scale',String(1-progress*.035));surface.style.setProperty('--stack-dim',String(progress*.24))});
 let current='home';sections.forEach((section,i)=>{if(sectionTops[i]<innerHeight*.45)current=section.id});document.querySelectorAll('.site-header nav a').forEach(link=>{if(link.getAttribute('href')==='#'+current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});}
function requestUpdate(){if(!scrollFrame&&!document.hidden)scrollFrame=requestAnimationFrame(renderScroll)}
addEventListener('scroll',requestUpdate,{passive:true,signal:listeners.signal});addEventListener('resize',requestUpdate,{passive:true,signal:listeners.signal});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(scrollFrame);scrollFrame=0}else requestUpdate()},eventOptions);
addEventListener('keydown',event=>{if(event.key==='Tab')keyboardNavigation=true},eventOptions);addEventListener('pointerdown',()=>{keyboardNavigation=false},{passive:true,signal:listeners.signal});document.addEventListener('focusin',event=>{if(!keyboardNavigation||!motionEnabled()||!desktopStack.matches)return;const card=event.target.closest('.project-card');if(!card)return;const stack=$('.project-stack'),index=cards.indexOf(card),gap=parseFloat(getComputedStyle(stack).rowGap)||0,top=stack.getBoundingClientRect().top+scrollY+cards.slice(0,index).reduce((sum,item)=>sum+item.offsetHeight+gap,0)-108;scrollTo({top,behavior:'instant'})},eventOptions);
addEventListener('pagehide',event=>{if(!event.persisted){listeners.abort();cancelAnimationFrame(scrollFrame)}else{cancelAnimationFrame(scrollFrame);scrollFrame=0}},eventOptions);addEventListener('pageshow',requestUpdate,eventOptions);


setLanguage(language);setMotion();

// Cursor lighting is local to the hovered panel and needs no continuous loop.
const hoverPointer=matchMedia('(hover: hover) and (pointer: fine)');
const heroPanel=document.querySelector('.hero.section-frame');
if(heroPanel){
 let heroPointerFrame=0,heroPointerX=0,heroPointerY=0;
 heroPanel.addEventListener('pointermove',event=>{
  if(!motionEnabled()||!hoverPointer.matches||event.pointerType!=='mouse')return;
  const rect=heroPanel.getBoundingClientRect();
  heroPointerX=event.clientX-rect.left;heroPointerY=event.clientY-rect.top;
  if(!heroPointerFrame)heroPointerFrame=requestAnimationFrame(()=>{
   heroPointerFrame=0;
   heroPanel.style.setProperty('--hero-pointer-x',`${heroPointerX}px`);
   heroPanel.style.setProperty('--hero-pointer-y',`${heroPointerY}px`);
  });
 },{passive:true,signal:listeners.signal});
 heroPanel.addEventListener('pointerleave',()=>{
  cancelAnimationFrame(heroPointerFrame);heroPointerFrame=0;
 },{passive:true,signal:listeners.signal});
 addEventListener('pagehide',()=>{cancelAnimationFrame(heroPointerFrame);heroPointerFrame=0},eventOptions);
}
document.querySelectorAll('.experience-panel, .bio-panel, .interests-panel, .interest-list li, .contact-channel').forEach(panel=>{
 panel.classList.add('hover-panel');
 panel.addEventListener('pointermove',event=>{
  if(!motionEnabled()||!hoverPointer.matches||event.pointerType!=='mouse')return;
  const rect=panel.getBoundingClientRect();
  panel.style.setProperty('--pointer-x',`${event.clientX-rect.left}px`);
  panel.style.setProperty('--pointer-y',`${event.clientY-rect.top}px`);
 },{passive:true,signal:listeners.signal});
 panel.addEventListener('pointerleave',()=>{
  panel.style.removeProperty('--pointer-x');panel.style.removeProperty('--pointer-y');
 },{passive:true,signal:listeners.signal});
});

// Reveal once on entry; keep content visible without JavaScript or when motion is off.
if ('IntersectionObserver' in window) {
 const revealTargets=document.querySelectorAll('.section-heading, .project-copy, .vexo-display, .dasturxon-display, .quantum-display, .about-summary>h2, .experience-panel, .bio-panel, .interests-heading, .interest-list li, .contact-heading, .contact-channel');
 const revealObserver=new IntersectionObserver(entries=>{
  entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-revealed');revealObserver.unobserve(entry.target)}});
 },{threshold:.08,rootMargin:'0px 0px -24px 0px'});
 revealTargets.forEach((element,index)=>{
  element.classList.add('scroll-reveal');
  element.style.setProperty('--reveal-delay',`${Math.min(index%3*65,130)}ms`);
  revealObserver.observe(element);
 });
 document.addEventListener('focusin',event=>{
  const target=event.target.closest('.scroll-reveal');
  if(target){target.classList.add('is-revealed');revealObserver.unobserve(target)}
 },eventOptions);
 addEventListener('pagehide',event=>{if(!event.persisted)revealObserver.disconnect()},eventOptions);
}
